// Generates PWA icons at build time (binary files can't be pushed via the content API).
const fs=require('fs'),path=require('path');
const ICONS={"icon-192.png": "", "icon-512.png": "", "icon-maskable-512.png": "", "apple-touch-icon.png": "", "favicon-32.png": ""};
const dir=path.join(__dirname,'..','src','assets','favicons','icons');fs.mkdirSync(dir,{recursive:true});
for(const [n,b] of Object.entries(ICONS)){fs.writeFileSync(path.join(dir,n),Buffer.from(b,'base64'));}
fs.copyFileSync(path.join(dir,'apple-touch-icon.png'),path.join(dir,'..','apple-touch-icon.png'));

// Brand images referenced by schema.org (logo) and Open Graph/Twitter cards (og-default).
const IMAGES={"logo.png":"","og-default.jpg":""};
const idir=path.join(__dirname,'..','src','assets','images');fs.mkdirSync(idir,{recursive:true});
for(const [n,v] of Object.entries(IMAGES)){fs.writeFileSync(path.join(idir,n),Buffer.from(v,'base64'));}
console.log('icons written:',Object.keys(ICONS).length);
